def migrate_inquiry_data(apps, schema_editor):
    Inquiry = apps.get_model("inquiries", "Inquiry")
    mapping = {"SUBMITTED": "NEW", "IN_PROGRESS": "ANALYZING"}
    for inquiry in Inquiry.objects.select_related("customer_account").all().iterator():
        customer = inquiry.customer_account
        inquiry.status = mapping.get(inquiry.status, inquiry.status)
        inquiry.customer_snapshot = {
            "customer_id": str(inquiry.customer_account_id),
            "customer_name": getattr(customer, "account_name", ""),
            "country_code": getattr(customer, "primary_country_code", getattr(customer, "country_code", "")),
        }
        inquiry.source_snapshot = {"source_code": inquiry.inquiry_source}
        if inquiry.owner_employee_id:
            inquiry.assigned_at = inquiry.updated_at or inquiry.created_at
        inquiry.save(update_fields=["status", "customer_snapshot", "source_snapshot", "assigned_at"])


def create_initial_assignment_history(apps, schema_editor):
    Inquiry = apps.get_model("inquiries", "Inquiry")
    History = apps.get_model("inquiries", "InquiryAssignmentHistory")
    History.objects.bulk_create([
        History(
            inquiry_id=inquiry.pk,
            new_owner_employee_id=inquiry.owner_employee_id,
            assignment_reason="历史负责人回填",
            assignment_type="INITIAL",
            assigned_at=inquiry.assigned_at or inquiry.updated_at or inquiry.created_at,
        )
        for inquiry in Inquiry.objects.exclude(owner_employee_id__isnull=True).iterator()
    ])


INQUIRY_TRIGGER_SQL = r"""
CREATE OR REPLACE FUNCTION haiqu_check_inquiry()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.transaction_entity_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM customer_transaction_entity entity
        WHERE entity.id = NEW.transaction_entity_id AND entity.customer_account_id = NEW.customer_account_id
    ) THEN
        RAISE EXCEPTION 'inquiry transaction entity must belong to the same customer account' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF NEW.customer_contact_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM customer_contact contact
        WHERE contact.id = NEW.customer_contact_id AND contact.customer_account_id = NEW.customer_account_id
    ) THEN
        RAISE EXCEPTION 'inquiry contact must belong to the same customer account' USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF NEW.status IN ('NEW', 'ANALYZING', 'READY_FOR_QUOTE', 'QUOTING', 'QUOTED', 'FOLLOW_UP', 'CONVERTED', 'LOST')
       AND NOT EXISTS (SELECT 1 FROM inquiry_item item WHERE item.inquiry_id = NEW.id) THEN
        RAISE EXCEPTION 'an active inquiry must contain at least one item' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE FUNCTION haiqu_check_inquiry_has_item()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM inquiry parent WHERE parent.id = OLD.inquiry_id
        AND parent.status IN ('NEW', 'ANALYZING', 'READY_FOR_QUOTE', 'QUOTING', 'QUOTED', 'FOLLOW_UP', 'CONVERTED', 'LOST'))
       AND NOT EXISTS (SELECT 1 FROM inquiry_item item WHERE item.inquiry_id = OLD.inquiry_id) THEN
        RAISE EXCEPTION 'an active inquiry must contain at least one item' USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NULL;
END;
$$;
"""


